mapper.sql:
r.status = '1'
and coalesce(r.audit_time, r.create_time) >= #{dayStart}
and coalesce(r.audit_time, r.create_time) < #{dayEnd}

w.status = '1'
and coalesce(w.audit_time, w.create_time) >= #{dayStart}
and coalesce(w.audit_time, w.create_time) < #{dayEnd}

mapper.select:
select date_format(coalesce(audit_time, create_time), '%Y-%m-%d') as dayKey, ifnull(sum(amount), 0) as amount
from biz_recharge
where status = '1' and currency = 'CNY'
  and coalesce(audit_time, create_time) >= #{begin}
  and coalesce(audit_time, create_time) < #{end}
group by date_format(coalesce(audit_time, create_time), '%Y-%m-%d')

select date_format(coalesce(audit_time, create_time), '%Y-%m-%d') as dayKey, ifnull(sum(amount), 0) as amount
from biz_withdraw
where status = '1' and currency = 'CNY'
  and coalesce(audit_time, create_time) >= #{begin}
  and coalesce(audit_time, create_time) < #{end}
group by date_format(coalesce(audit_time, create_time), '%Y-%m-%d')
